{
  "claims": [
    {
      "claim_text": "Some SQLite limits can be changed per connection at run time with sqlite3_limit().",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] directly states that some limits can be changed at run-time on a per-connection basis using sqlite3_limit().",
      "citations": [
        {
          "index": 0,
          "quote": "Some limits can be changed at run-time on a per-connection basis using the sqlite3_limit() interface with one of the limit categories defined for that interface."
        }
      ]
    },
    {
      "claim_text": "The 64-table join limit is not one of the limits that can be changed per connection at run time with sqlite3_limit().",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] identifies the 64-table join limit, and passage [2] says there is no mechanism to raise or lower the limit on the number of tables in a join.",
      "citations": [
        {
          "index": 1,
          "quote": "SQLite does not support joins containing more than 64 tables."
        },
        {
          "index": 2,
          "quote": "Hence, there is no mechanism to raise or lower the limit on the number of tables in a join."
        }
      ]
    },
    {
      "claim_text": "If SQLITE_MAX_EXPR_DEPTH is compiled as 0, expression depth is unlimited.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] states that setting SQLITE_MAX_EXPR_DEPTH to 0 at compile time means the depth of expressions is unlimited.",
      "citations": [
        {
          "index": 4,
          "quote": "If SQLITE_MAX_EXPR_DEPTH is set to 0 at compile time (if the depth of expressions is unlimited) then the sqlite3_limit(db,SQLITE_LIMIT_EXPR_DEPTH,size) is a no-op."
        }
      ]
    },
    {
      "claim_text": "If SQLITE_MAX_EXPR_DEPTH is compiled as 0, calling sqlite3_limit() with SQLITE_LIMIT_EXPR_DEPTH cannot impose a limit.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] says that when SQLITE_MAX_EXPR_DEPTH is 0 at compile time, calling sqlite3_limit with SQLITE_LIMIT_EXPR_DEPTH is a no-op.",
      "citations": [
        {
          "index": 4,
          "quote": "If SQLITE_MAX_EXPR_DEPTH is set to 0 at compile time (if the depth of expressions is unlimited) then the sqlite3_limit(db,SQLITE_LIMIT_EXPR_DEPTH,size) is a no-op."
        }
      ]
    },
    {
      "claim_text": "A web browser could use sqlite3_limit() to keep its internal history database unconstrained.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] gives a web browser with an internal history database as an example and says sqlite3_limit() allows internal databases managed by trusted code to be unconstrained.",
      "citations": [
        {
          "index": 0,
          "quote": "For example, a web browser application might use an internal database to track historical page views but have one or more separate databases that are created and controlled by javascript applications that are downloaded from the internet. The sqlite3_limit() interface allows internal databases managed by trusted code to be unconstrained while simultaneously placing tight limitations on databases created or controlled by untrusted external code in order to help prevent a denial of service attack."
        }
      ]
    },
    {
      "claim_text": "A web browser could use sqlite3_limit() to tightly limit databases created by downloaded JavaScript.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] describes web browser databases created and controlled by downloaded javascript applications and says sqlite3_limit() places tight limitations on databases created or controlled by untrusted external code.",
      "citations": [
        {
          "index": 0,
          "quote": "For example, a web browser application might use an internal database to track historical page views but have one or more separate databases that are created and controlled by javascript applications that are downloaded from the internet. The sqlite3_limit() interface allows internal databases managed by trusted code to be unconstrained while simultaneously placing tight limitations on databases created or controlled by untrusted external code in order to help prevent a denial of service attack."
        }
      ]
    },
    {
      "claim_text": "At the default 4096-byte page size, a database tops out at about 17.5 TB.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [5] states that with the default page size of 4096 bytes, the maximum database size is about 17.5 terabytes.",
      "citations": [
        {
          "index": 5,
          "quote": "When used with the default page size of 4096 bytes, this gives a maximum database size of about 17.5 terabytes."
        }
      ]
    },
    {
      "claim_text": "A database with the default 4096-byte page size can hold up to about 2e+13 rows.",
      "verdict": "UNSUPPORTED",
      "reasoning": "Passage [6] ties the approximately 2e+13 row figure to a 281-terabyte database, not to the default page-size maximum of about 17.5 TB.",
      "citations": []
    },
    {
      "claim_text": "Raising the page size to 65536 bytes multiplies the maximum database size by 16.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [5] gives about 17.5 TB at 4096-byte pages and about 281 TB at 65536-byte pages; 65536 is 16 times 4096 and 281 is about 16 times 17.5.",
      "citations": [
        {
          "index": 5,
          "quote": "When used with the default page size of 4096 bytes, this gives a maximum database size of about 17.5 terabytes. If the page size is increased to the maximum of 65536 bytes, then the database file can grow to be as large as about 281 terabytes."
        }
      ]
    },
    {
      "claim_text": "Most applications are expected to need higher limits rather than lower ones.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [7] says increases are rare and that more commonly an application might want to recompile SQLite with much lower limits.",
      "citations": [
        {
          "index": 7,
          "quote": "Some applications may want to increase a limit here or there, but we expect such needs to be rare. More commonly, an application might want to recompile SQLite with much lower limits to avoid excess resource utilization in the event of bugs in higher-level SQL statement generators or to help thwart attackers who inject malicious SQL statements."
        }
      ]
    }
  ]
}
